declare(strict_types=1);require_once __DIR__.'/estimate_common.php';$user=billing_require_admin();production_require_method('POST');$in=production_input();accounts_endpoint(function()use($user,$in):array{$id=(int)($in['estimate_id']??0);$mime=strtolower(trim((string)($in['mime_type']??'')));if(!in_array($mime,['image/jpeg','image/png','application/pdf'],true))accounts_fail('UNSUPPORTED_EVIDENCE_TYPE');$name=production_clean_text($in['filename']??'',255,'EVIDENCE_FILENAME_REQUIRED');$bytes=base64_decode((string)($in['data_base64']??''),true);if($bytes===false||$bytes===''||strlen($bytes)>8*1024*1024)accounts_fail('INVALID_EVIDENCE_DATA');$db=production_db();return accounts_transaction($db,function()use($db,$user,$id,$mime,$name,$bytes):array{$e=estimate_locked($db,$id);if($e['status']!=='SENT')accounts_fail('ESTIMATE_NOT_ACCEPTABLE',409);$hash=hash('sha256',$bytes);$q=$db->prepare('INSERT INTO qbook_estimate_acceptance_evidence(estimate_id,original_filename,mime_type,byte_size,sha256,evidence_data,uploaded_by)VALUES(?,?,?,?,?,?,?)');$q->bindValue(1,$id,PDO::PARAM_INT);$q->bindValue(2,$name);$q->bindValue(3,$mime);$q->bindValue(4,strlen($bytes),PDO::PARAM_INT);$q->bindValue(5,$hash);$q->bindValue(6,$bytes,PDO::PARAM_LOB);$q->bindValue(7,$user['id'],PDO::PARAM_INT);$q->execute();$eid=(int)$db->lastInsertId();accounts_audit($db,$user,'ESTIMATE_ACCEPTANCE_EVIDENCE_UPLOADED','ESTIMATE',$id,['evidence_id'=>$eid,'sha256'=>$hash]);return['evidence'=>['id'=>$eid,'filename'=>$name,'sha256'=>$hash]];});});
